#include <cstdint>
#include <functional>
#include <map>
#include <optional>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

using Message = std::vector<std::uint8_t>;
using Method = std::function<std::string(const std::vector<std::string>&)>;

namespace wire
{
    inline void id(Message& m, std::uint32_t v) { for (int i{ 0 }; i < 4; ++i) m.push_back(static_cast<std::uint8_t>(v >> (8 * i))); }
    inline void str(Message& m, const std::string& s)
    {
        m.push_back(static_cast<std::uint8_t>(s.size()));
        m.push_back(static_cast<std::uint8_t>(s.size() >> 8));
        m.insert(m.end(), s.begin(), s.end());
    }
    inline void list(Message& m, const std::vector<std::string>& l) { m.push_back(static_cast<std::uint8_t>(l.size())); for (const auto& s : l) str(m, s); }

    struct Reader
    {
        const Message& m;
        std::size_t at{ 0 };
        bool ok{ true };
        std::uint8_t byte() { if (at + 1 > m.size()) { ok = false; return 0; } return m[at++]; }
        std::uint32_t u32() { std::uint32_t v{ 0 }; for (int i{ 0 }; i < 4; ++i) v |= static_cast<std::uint32_t>(byte()) << (8 * i); return v; }
        std::string str()
        {
            const std::size_t n{ static_cast<std::size_t>(byte() | (byte() << 8)) };
            if (!ok || at + n > m.size()) { ok = false; return ""; }
            std::string s(m.begin() + static_cast<std::ptrdiff_t>(at), m.begin() + static_cast<std::ptrdiff_t>(at + n));
            at += n;
            return s;
        }
        std::vector<std::string> list() { std::vector<std::string> l; const int n{ byte() }; for (int i{ 0 }; i < n && ok; ++i) l.push_back(str()); return l; }
        bool finished() const { return ok && at == m.size(); }
    };

    inline Message make(std::uint8_t type, std::uint32_t idValue) { Message m{ type }; id(m, idValue); return m; }
}

class RpcServer
{
public:
    void method(const std::string& name, Method fn) { methods[name] = std::move(fn); }

    Message handle(const Message& incoming)
    {
        wire::Reader r{ incoming };
        const std::uint8_t type{ r.byte() };
        const std::uint32_t id{ r.u32() };
        const std::string name{ r.str() };
        const std::vector<std::string> args{ r.list() };
        if (type != 1 || !r.finished()) return error(0, "malformed message");
        const auto it{ methods.find(name) };
        if (it == methods.end()) return error(id, "unknown method " + name);
        try
        {
            Message m{ wire::make(2, id) };
            wire::str(m, it->second(args));
            return m;
        }
        catch (const std::invalid_argument& e) { return error(id, e.what()); }
    }

    Message event(const std::string& name, const std::vector<std::string>& args)
    {
        Message m{ wire::make(4, 0) };
        wire::str(m, name);
        wire::list(m, args);
        return m;
    }

private:
    std::map<std::string, Method> methods;

    static Message error(std::uint32_t id, const std::string& text)
    {
        Message m{ wire::make(3, id) };
        wire::str(m, text);
        return m;
    }
};

class RpcClient
{
public:
    Message call(const std::string& method, const std::vector<std::string>& args, std::uint64_t now, std::uint64_t timeout, std::uint32_t& id)
    {
        id = next++;
        pending[id] = now + timeout;
        Message m{ wire::make(1, id) };
        wire::str(m, method);
        wire::list(m, args);
        return m;
    }

    void handle(const Message& incoming)
    {
        wire::Reader r{ incoming };
        const std::uint8_t type{ r.byte() };
        const std::uint32_t id{ r.u32() };
        if (type == 2 || type == 3)
        {
            const std::string text{ r.str() };
            if (!r.finished() || !pending.count(id)) return;
            pending.erase(id);
            (type == 2 ? results : errors)[id] = text;
        }
        else if (type == 4)
        {
            const std::string name{ r.str() };
            auto args{ r.list() };
            if (r.finished()) events.push_back({ name, std::move(args) });
        }
    }

    std::optional<std::string> result(std::uint32_t id) { return take(results, id); }
    std::optional<std::string> error(std::uint32_t id) { return take(errors, id); }

    std::vector<std::uint32_t> expire(std::uint64_t now)
    {
        std::vector<std::uint32_t> out;
        for (auto it{ pending.begin() }; it != pending.end();)
        {
            if (it->second <= now) { out.push_back(it->first); it = pending.erase(it); }
            else ++it;
        }
        return out;
    }

    std::vector<std::pair<std::string, std::vector<std::string>>> takeEvents()
    {
        auto out{ std::move(events) };
        events.clear();
        return out;
    }

private:
    std::uint32_t next{ 1 };
    std::map<std::uint32_t, std::uint64_t> pending;
    std::map<std::uint32_t, std::string> results, errors;
    std::vector<std::pair<std::string, std::vector<std::string>>> events;

    static std::optional<std::string> take(std::map<std::uint32_t, std::string>& from, std::uint32_t id)
    {
        const auto it{ from.find(id) };
        if (it == from.end()) return std::nullopt;
        std::string v{ it->second };
        from.erase(it);
        return v;
    }
};

unitTests:
static RpcServer makeServer()
{
    RpcServer s;
    s.method("add", [](const std::vector<std::string>& a) {
        if (a.size() != 2) throw std::invalid_argument("add needs 2 arguments");
        return std::to_string(std::stoll(a[0]) + std::stoll(a[1]));
    });
    s.method("echo", [](const std::vector<std::string>& a) { std::string out; for (const auto& x : a) out += x; return out; });
    return s;
}

TEST("the exact bytes of a request") {
    RpcClient c;
    std::uint32_t id{};
    const Message m{ c.call("add", { "2", "40" }, 0, 100, id) };
    CHECK_EQ(id, 1u);
    CHECK(m == (Message{ 1, 1, 0, 0, 0, 3, 0, 'a', 'd', 'd', 2, 1, 0, '2', 2, 0, '4', '0' }));
}
TEST("a call and its result") {
    RpcServer s{ makeServer() };
    RpcClient c;
    std::uint32_t id{};
    c.handle(s.handle(c.call("add", { "2", "40" }, 0, 100, id)));
    CHECK_EQ(c.result(id).value_or("?"), std::string("42"));
    CHECK(!c.result(id).has_value());
}
TEST("errors") {
    RpcServer s{ makeServer() };
    RpcClient c;
    std::uint32_t a{}, b{};
    c.handle(s.handle(c.call("fly", {}, 0, 100, a)));
    c.handle(s.handle(c.call("add", { "1" }, 0, 100, b)));
    CHECK_EQ(c.error(a).value_or("?"), std::string("unknown method fly"));
    CHECK_EQ(c.error(b).value_or("?"), std::string("add needs 2 arguments"));
    CHECK(!c.result(a).has_value());
    const Message bad{ s.handle(Message{ 1, 9, 0 }) };
    CHECK(bad == (Message{ 3, 0, 0, 0, 0, 17, 0, 'm', 'a', 'l', 'f', 'o', 'r', 'm', 'e', 'd', ' ', 'm', 'e', 's', 's', 'a', 'g', 'e' }));
}
TEST("several in flight, answered out of order") {
    RpcServer s{ makeServer() };
    RpcClient c;
    std::uint32_t a{}, b{};
    const Message ra{ c.call("echo", { "x" }, 0, 100, a) };
    const Message rb{ c.call("echo", { "y", "z" }, 0, 100, b) };
    c.handle(s.handle(rb));
    c.handle(s.handle(ra));
    CHECK_EQ(c.result(a).value_or("?"), std::string("x"));
    CHECK_EQ(c.result(b).value_or("?"), std::string("yz"));
}
TEST("timeouts and late answers") {
    RpcServer s{ makeServer() };
    RpcClient c;
    std::uint32_t slow{}, fast{};
    const Message request{ c.call("echo", { "late" }, 0, 50, slow) };
    c.call("echo", { "ok" }, 10, 500, fast);
    CHECK_EQ(c.expire(60), std::vector<std::uint32_t>{ slow });
    c.handle(s.handle(request));
    CHECK(!c.result(slow).has_value());
    CHECK(c.expire(1000) == std::vector<std::uint32_t>{ fast });
}
TEST("events") {
    RpcServer s{ makeServer() };
    RpcClient c;
    c.handle(s.event("fileChanged", { "a.cpp" }));
    c.handle(s.event("buildFinished", { "ok", "3.2s" }));
    c.handle(Message{ 4, 0 });
    const auto events{ c.takeEvents() };
    CHECK_EQ(events.size(), 2u);
    if (events.size() == 2) { CHECK_EQ(events[0].first, std::string("fileChanged")); CHECK_EQ(events[1].second.size(), 2u); }
    CHECK(c.takeEvents().empty());
}

